-- Clustered index fiziki ardıcıllığı təyin edir
CREATE CLUSTERED INDEX IX_Policies_PolicyID ON dbo.Policies(PolicyID);

-- Non-Clustered index axtarışı sürətləndirən ayrıca strukturdur
CREATE NONCLUSTERED INDEX IX_Policies_CustomerID ON dbo.Policies(CustomerID)
INCLUDE (Premium, StartDate);
